import re

HEADER = re.compile(r"^Class\s+I\s+H/W Path\s+Driver")
RULE = re.compile(r"^=+\s*$")
DEVICE = re.compile(r"^(?P<cls>\S+)\s+(?P<i>\d+)\s+(?P<hw>\S+)\s+(?P<driver>\S+)\s+(?P<sw>\S+)\s+(?P<hwtype>\S+)\s+(?P<desc>\S.*?)\s*$")
FILES = re.compile(r"^\s+(?P<files>/dev/\S+(?:\s+/dev/\S+)*)\s*$")


def parse(lines):
    devices = {"name": "devices", "kind": "table", "lines": [], "records": []}
    skip, cur = [], None
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        if RULE.match(ln):
            skip.append(i)
            continue
        if HEADER.match(ln):
            devices["lines"].append(i)
            continue
        m = DEVICE.match(ln)
        if m:
            cur = {"Class": m.group("cls"), "I": m.group("i"), "H/W Path": m.group("hw"), "Driver": m.group("driver"),
                   "S/W State": m.group("sw"), "H/W Type": m.group("hwtype"), "Description": m.group("desc"),
                   "Device file": "", "Raw device file": ""}
            devices["records"].append(cur)
            devices["lines"].append(i)
            continue
        m = FILES.match(ln)
        if m and cur is not None:
            files = m.group("files").split()
            for key, val in zip(("Device file", "Raw device file"), files + [""] * (2 - len(files))):
                if val:
                    cur[key] = (cur[key] + "," + val) if cur[key] else val
            devices["lines"].append(i)
    return {"blocks": [devices], "skip": skip}
